//! Byte-for-byte parity of the writer with the C reference's
//! `bovnar pretty-print`.
//!
//! `tests/writer/pretty.json` holds the C output for every valid input of
//! the conformance corpus (cases without limit overrides) and for the
//! upstream `examples/*.bvnr`. It was generated by running
//! `bovnar pretty-print <file>` of the C reference build (UCUM and CF off)
//! over each input and recording stdout as base64.
//!
//! Two paths are checked: the reader driving the writer event by event (what
//! `pretty-print` itself does), and parse → [`bovnar::to_vec`] through the
//! document tree, which must reproduce the same bytes.

use base64::engine::general_purpose::STANDARD;
use base64::Engine as _;
use bovnar::{Limits, Reader, Writer};
use serde_json::Value;

const FIXTURE: &str = include_str!("writer/pretty.json");

fn decode(v: &Value) -> Vec<u8> {
    STANDARD
        .decode(v.as_str().expect("base64 field"))
        .expect("valid base64")
}

/// The reader feeding the writer directly, at the format's nesting cap.
fn stream_pretty(input: &[u8]) -> Result<Vec<u8>, bovnar::Error> {
    let mut limits = Limits::default();
    limits.max_struct_nesting = 255;
    limits.max_array_nesting = 255;
    // Like `pretty-print`, learn the version first: a directive is only
    // known once the reader has seen what follows it.
    let mut peek = Reader::new(&limits);
    let _ = peek.feed(input);
    let _ = peek.finish();
    let mut reader = Reader::new(&limits);
    let mut writer = Writer::with_limits(Vec::new(), true, &limits);
    if let Some(version) = peek.declared_version() {
        writer.write_version(version)?;
    }
    let fed = reader.feed(input);
    while let Some(event) = reader.next_event() {
        writer.write_event(&event)?;
    }
    fed?;
    let finished = reader.finish();
    while let Some(event) = reader.next_event() {
        writer.write_event(&event)?;
    }
    finished?;
    writer.finish()?;
    Ok(writer.into_sink())
}

#[test]
fn pretty_print_parity() {
    let fixture: Value = serde_json::from_str(FIXTURE).expect("fixture is JSON");
    let cases = fixture["cases"].as_array().expect("case list");
    let mut failures = Vec::new();
    let mut dom_skipped = 0usize;
    let mut unread = 0usize;
    let mut rechunked = 0usize;
    for case in cases {
        let id = case["id"].as_str().unwrap_or("?");
        let input = decode(&case["input"]);
        let want = decode(&case["stdout"]);
        // Parity is about the writer: inputs this reader does not accept yet
        // (unit profiles not built in) are left to the conformance test.
        if bovnar::read_all(&input, &dom_limits(), |_| {}).is_err() {
            unread += 1;
            continue;
        }
        match stream_pretty(&input) {
            Ok(got) if got == want => {}
            Ok(got) => failures.push(format!(
                "{id} (stream): expected {:?}, got {:?}",
                String::from_utf8_lossy(&want),
                String::from_utf8_lossy(&got)
            )),
            Err(e) => failures.push(format!("{id} (stream): error {}", e.kind().as_str())),
        }
        // Inputs the document tier refuses (duplicate keys, mixed arrays)
        // are pretty-printed by the stream path only.
        let Ok(doc) = bovnar::parse_with(&input, &dom_limits()) else {
            dom_skipped += 1;
            continue;
        };
        match bovnar::to_vec(&doc) {
            Ok(got) if got == want => {}
            // The tree keeps an octet stream's bytes, not the chunks they
            // came in; the same bytes in other chunks are the same document.
            Ok(got)
                if has_octets(&doc) && bovnar::parse(&got).ok() == bovnar::parse(&want).ok() =>
            {
                rechunked += 1;
            }
            Ok(got) => failures.push(format!(
                "{id} (dom): expected {:?}, got {:?}",
                String::from_utf8_lossy(&want),
                String::from_utf8_lossy(&got)
            )),
            Err(e) => failures.push(format!("{id} (dom): error {}", e.kind().as_str())),
        }
    }
    println!(
        "{} cases: {unread} not readable here, {dom_skipped} refused by the document tier, \
         {rechunked} equal up to octet chunking",
        cases.len()
    );
    for f in &failures {
        println!("FAIL {f}");
    }
    assert!(failures.is_empty(), "{} parity failures", failures.len());
}

fn dom_limits() -> Limits {
    let mut limits = Limits::default();
    limits.max_struct_nesting = 255;
    limits.max_array_nesting = 255;
    limits
}

fn has_octets(doc: &bovnar::Document) -> bool {
    let mut stack: Vec<&bovnar::Value> = doc.iter().map(|(_, v)| v).collect();
    while let Some(v) = stack.pop() {
        match v.kind() {
            bovnar::Kind::Octets(_) => return true,
            bovnar::Kind::Struct(s) => stack.extend(s.iter().map(|(_, v)| v)),
            bovnar::Kind::Array(a) => stack.extend(a.iter()),
            _ => {}
        }
    }
    false
}
